/* COMP5618 — quiz bank.
 * Entry shape: { ch, type: "study"|"math", q, opts: [..], answer: <index>, exp }
 *
 * Grouped by chapter index (Ch1 = Week 1 … Ch7 = Week 8). `answer` is the
 * ZERO-BASED index into `opts`. "math" entries come from the chapter's
 * Foundations page, "study" entries from its study guide.
 */
var ALL_QUIZ_DATA = [

  /* Ch1 */
  { ch: 1, type: "study", q: "During an authorised test, a single request lets you read another customer's invoice. Which property of the CIA triad have you demonstrated, and what is the correct next step?", opts: ["Availability — check that the service is still responding, then continue", "Confidentiality — stop, capture the minimum evidence that proves the flaw, and report it", "Integrity — revert anything the request changed and document the change", "None — reading data during an authorised test breaks no property"], answer: 1, exp: "Disclosure to someone not authorised to read it is a confidentiality break. The Week 1 rule is to take the minimum evidence that establishes the class of data, then stop — 'be thorough' is not an instruction to keep reading records." },
  { ch: 1, type: "study", q: "A client has signed a scope and then says verbally: 'have a go at anything else you can reach while you are in there.' What is the correct action?", opts: ["Test the extra systems, because the client gave permission", "Test them silently and disclose everything you touched in the final report", "Decline until the extra systems are named in the written scope, and record the exchange", "Test them only if they are on the same subnet as an in-scope host"], answer: 2, exp: "Authorisation is written, prior, specific and current. A verbal addition fails 'written' and 'specific', and a host that merely appeared in your results was never in scope. Anything you touch outside the signed scope falls on the offence side of the membership test." },
  { ch: 1, type: "study", q: "A student runs a port scan against the university's public web server from home and argues that no offence occurred because nothing was exploited. Which response matches the Week 1 material?", opts: ["A scan is passive observation, so it falls outside the offence", "It is lawful provided no damage was intended", "The scan is itself unauthorised activity — the deck warns that reconnaissance without permission can be treated as an offence", "It is lawful because a public web server is reachable by anyone"], answer: 2, exp: "The deck is explicit that using penetration tools against any system on a public network without prior permission is unlawful, and that this can extend to reconnaissance. 'It was easy' and 'I only looked' are not defences." },
  { ch: 1, type: "study", q: "You have installed Kali and Ubuntu as VirtualBox guests with the default NAT networking. Both reach the internet but neither can ping the other. What is the correct fix?", opts: ["Switch both guests to bridged networking so they share your local network", "Configure port-forwarding rules on the existing NAT adapters", "Disable the guests' firewalls until the ping succeeds", "Add a second NIC to each guest set to host-only adapter, then verify the addresses with ifconfig"], answer: 3, exp: "Bridged networking would put the guests on a real network and destroy the isolation the unit depends on. NAT is not a segment the two guests share. The lab calls for one host-only network with a second host-only NIC in each guest, verified by both addresses sitting inside the host-only range." },
  { ch: 1, type: "study", q: "An nmap run from Kali against the Ubuntu guest reports port 22 open. What is the most useful next step in the Week 1 lab?", opts: ["Re-run the same scan with a different technique to confirm the result", "Immediately attempt to escalate privileges on the Ubuntu guest", "Log in over SSH from Kali, because port 22 is the service Tutorial 1 enabled for exactly that purpose", "Block port 22 on the firewall and re-scan to prove the rule works"], answer: 2, exp: "Tutorial 1 has you enable an SSH server on Ubuntu and log in from Kali, so an open 22 is the expected, intended finding rather than a vulnerability. Privilege escalation belongs to Week 6, and re-scanning with another technique proves nothing new." },
  { ch: 1, type: "study", q: "You hold written permission for a /24 subnet in a four-hour window. At hour three, results include a host whose address belongs to the client's payment provider. What do you do?", opts: ["Continue — the address fell inside the range you were given", "Finish the scan quietly and mention it in the report afterwards", "Treat it as an in-scope host, since the client owns the service", "Exclude the host immediately, record what you saw, and raise it with the client before continuing"], answer: 3, exp: "Scope names systems you are authorised to touch, not everything that answers inside an address range. The Week 1 rule for x ∉ S is: record it, exclude it, raise it with the client. Continuing quietly turns an authorised test into unauthorised activity." },
  { ch: 1, type: "study", q: "A hospital reviews an incident in which a clerk accidentally e-mailed a patient spreadsheet to the wrong distribution list. Which adversary row does this belong to, and what follows for the control you recommend?", opts: ["A state-sponsored attacker — so recommend network monitoring and attribution", "A malicious insider — so recommend audit trails and dismissal", "An inadvertent insider — so the control must limit what legitimate access can reach, not deny access", "An external hacker — so recommend perimeter filtering of outbound mail"], answer: 2, exp: "The clerk was trying to do their job and held legitimate access, so controls that deny access are useless. The Week 1 row for an inadvertent insider points at least privilege, review of who can export what, and limits on bulk export." },
  { ch: 1, type: "math", q: "Which of these is the exact Week 1 definition of an adversary?", opts: ["A skilled attacker who breaks into systems for personal gain", "Anyone who uses network technologies to gain unauthorised access to a system", "An employee who misuses the access their job gives them", "A person who writes and sells malicious software"], answer: 1, exp: "The definition is deliberately not a list of people: it is defined by the absence of authorisation, which is why the same action is professional testing inside a signed scope and an offence outside it. 'A hacker' with no reference to authorisation loses the mark." },
  { ch: 1, type: "math", q: "A scope is signed on Monday for a two-week window covering a named subnet. On day nine the client's employee verbally asks you to also check a new staging server with a different address. Which conditions of P = written ∧ prior ∧ specific ∧ current have failed?", opts: ["Current only — a two-week scope cannot be extended mid-engagement", "Prior only — permission should always be arranged in advance", "Written and specific — the addition is verbal and the staging server is not a named target", "None — an employee of the client can extend scope verbally"], answer: 2, exp: "'Written' rules out the verbal go-ahead, and 'specific' rules out the staging host because scope names systems, IP addresses and time windows. The window has not expired on day nine, so 'current' still holds." },
  { ch: 1, type: "math", q: "Your lab guest can reach the internet as well as the other guest. Which statement about that situation is correct?", opts: ["It is harmless, because you only ever type addresses that are in scope", "Isolation has failed — the segment is bridged or NATed, so a mis-typed address would leave the lab; fix the adapter before testing", "It is acceptable provided you capture traffic on the host-only interface", "It is acceptable if you keep the firewall on the guest enabled"], answer: 1, exp: "The lab's isolation is itself a legal control. The verification checklist tests 'no route out' precisely because a guest with internet access is a guest from which a mistyped address reaches a third party — and reconnaissance without permission counts as an offence." },

  /* Ch2 */
  { ch: 2, type: "study", q: "A capture shows a 60-byte Ethernet frame (excluding the FCS) carrying a 28-byte ARP request. Why is the frame not simply 14 + 28 + 4 = 46 bytes?", opts: ["The payload has been encrypted, which adds bytes", "The 8-byte preamble and the SFD are counted in the captured length", "The payload is padded with zeros to reach the 46-byte minimum, so the frame reaches the 64-byte minimum size", "Wireshark rewrites short frames to a fixed display length"], answer: 2, exp: "Ethernet pads any payload below 46 bytes. 14 + 46 + 4 = 64 bytes, the minimum frame size, which existed so that collision detection still worked on a shared half-duplex segment. The ARP dissector ignores the trailing zero padding." },
  { ch: 2, type: "study", q: "Your capture shows a device whose MAC address begins 00:1A:2B. What have you actually learned?", opts: ["The vendor block the interface was allocated from, which may hint at the device class", "The network the device is currently attached to", "Proof that the frame genuinely came from that manufacturer's device", "That the address is locally administered rather than factory-assigned"], answer: 0, exp: "The first 24 bits are the OUI — an IEEE vendor block. A MAC is flat and non-hierarchical, so it encodes no network, and nothing authenticates it: a locally administered address (U/L bit = 1) can claim any OUI while staying syntactically valid." },
  { ch: 2, type: "study", q: "Why is an ARP request sent to FF:FF:FF:FF:FF:FF while the reply is unicast?", opts: ["The request is larger, so it needs the extra bandwidth of a broadcast", "The requester knows only the IP address it wants; the responder already learned the requester's MAC from the request", "Both are broadcast, and the reply only looks unicast in a capture", "ARP replies must be unicast because switches drop broadcast replies"], answer: 1, exp: "The sender has an IP and needs a MAC, so it must ask everyone in the broadcast domain and zeroes the target MAC field. The target already has the requester's MAC from the request, so it answers directly — and both sides cache the mapping, which is why a second exchange with the same host is silent." },
  { ch: 2, type: "study", q: "Two hosts are connected to the same physical switch but are assigned to different VLANs. What is true?", opts: ["They receive each other's broadcast frames just as if they shared a VLAN", "They are isolated at Layer 2 and need a Layer 3 device to communicate", "They merge into one broadcast domain as soon as the inter-switch link becomes a trunk", "They can communicate only if both use locally administered MAC addresses"], answer: 1, exp: "Ports with the same VLAN ID behave as one virtual switch, and ports in different VLANs are on different virtual switches. Traffic cannot cross without a Layer 3 device — that is the point of segmentation: task separation, less overhead and a smaller blast radius." },
  { ch: 2, type: "study", q: "You set a capture filter of arp on a busy link and record for an hour. What have you lost?", opts: ["Nothing important — capture filters only hide frames and they can be revealed later", "Every non-ARP frame: it was discarded at capture time and is not in the file", "Only the ARP frames are highlighted; the rest are present but greyed out", "Only the non-ARP payloads; all Layer 2 headers are still recorded"], answer: 1, exp: "A capture filter uses BPF syntax and is applied before capture begins, so non-matching traffic is dropped and unrecoverable. A Wireshark display filter is the reversible one — it hides frames that are still in the file." },
  { ch: 2, type: "study", q: "Why does MAC flooding make a switch leak unicast traffic?", opts: ["The MAC table overflows, and an unresolvable unicast is flooded out of every other port in the VLAN", "The VLAN configuration is overwritten, merging every VLAN into one", "The switch stops checking the FCS and forwards corrupt frames", "The switch converts every unicast frame into a broadcast frame on all VLANs"], answer: 0, exp: "The CAM table has finite memory; once it is full, entries cannot be learned, and the switch's rule for an unknown unicast is to flood it. Port security that limits learned addresses per port — and shuts the port rather than failing open — is the control." },
  { ch: 2, type: "study", q: "In Tutorial 2 you forward a local port through a jump host so Kali can browse a web server that only the jump host can reach. Why can the same tunnel not carry an ICMP echo request?", opts: ["ICMP is encrypted by an IPsec layer that SSH cannot decrypt", "The jump host's firewall always blocks ICMP, so the tunnel never opens", "SSH forwards a TCP stream, and ICMP is neither TCP nor UDP, so there is nothing to carry", "ICMP is a Layer 2 protocol and the tunnel terminates at Layer 4"], answer: 2, exp: "ssh -L carries one TCP conversation at the application layer. When the whole private network has to be reachable — many ports, many hosts, or non-TCP protocols such as ICMP — the tutorial configures OpenVPN, because a VPN carries IP rather than one stream." },
  { ch: 2, type: "math", q: "A standard untagged Ethernet frame carries a 1200-byte payload. What is its total size on the wire, excluding preamble and inter-frame gap?", opts: ["1200 bytes, because the payload is below the MTU", "1218 bytes", "1246 bytes, because the frame is padded to a 46-byte multiple", "1222 bytes, because the 802.1Q tag adds 4 bytes"], answer: 1, exp: "F = H + P + T = 14 + 1200 + 4 = 1218 bytes. Padding only applies below 46 bytes of payload, 1200 is under the 1500-byte MTU so nothing is padded, and the tag is only present on a tagged frame, giving 1222." },
  { ch: 2, type: "math", q: "A capture holds two frames. The first declares EtherType 0x0806 and carries no transport header at all; the second declares EtherType 0x0800 and carries a UDP datagram whose destination port is 53. What is in each frame?", opts: ["An IPv6 packet carrying DNS, then an 802.1Q-tagged frame carrying SNMP", "An ARP message, then an IPv4 packet carrying DNS", "An IPv4 packet carrying ARP, then a UDP datagram carrying MySQL", "An 802.1Q tag, then a TCP segment carrying SSH"], answer: 1, exp: "From the EtherType table: 0x0800 is IPv4, 0x0806 is ARP, 0x86DD is IPv6 and 0x8100 is an 802.1Q tag. ARP is a link-layer helper that straddles the Layer 2/3 boundary and has no transport header, while UDP port 53 is DNS — one of the UDP services the week names alongside DHCP and SNMP. MySQL's 3306 is the port the SSH local-forward example reaches, not 53." },
  { ch: 2, type: "math", q: "A 20 MHz Wi-Fi channel is measured at 30 dB SNR. Using Shannon, roughly what is the capacity ceiling?", opts: ["About 160 Mbit/s, from 2B log2 M with 16 levels", "About 199 Mbit/s, because SNR = 1000 and log2(1001) ≈ 9.97", "About 20 Mbit/s, because the bandwidth is 20 MHz", "About 1 Gbit/s, because 30 dB of SNR is a very strong signal"], answer: 1, exp: "30 dB means 10 log10(S/N) = 30, so S/N = 1000, and C = 20×10^6 × log2(1001) ≈ 1.99×10^8 bit/s. The Nyquist figure of 160 Mbit/s is the noiseless idealisation; Shannon's noisy bound is the real ceiling, and no encoding escapes it." },

  /* Ch3 */
  { ch: 3, type: "study", q: "A router permits the finance subnet to reach the printer subnet, and permits printer → finance traffic only as replies to those connections. What does this achieve?", opts: ["The printer network is completely isolated from the finance subnet", "A compromised printer cannot originate connections into finance, so it cannot scan those hosts", "It prevents an attacker from using firewalking against the router", "It guarantees the printer's replies are encrypted in transit"], answer: 1, exp: "Reachability is directional and the direction is deliberate: finance may initiate, the printer may only answer. Cutting off initiated traffic stops a rogue or compromised printer from reaching into finance, while a stateful device still admits the replies by matching them to the flow it already permitted." },
  { ch: 3, type: "study", q: "A scanner sends a SYN and receives nothing back, even after the timeout. Which conclusion is defensible?", opts: ["The port is closed, because no service replied", "The port is open but the service is slow to answer", "The port is filtered or open — a silent drop is indistinguishable from a listener that never answers", "The host is down, because a live host always answers a SYN"], answer: 2, exp: "SYN, ACK means open; RST means the host is alive and the port is closed; silence means something in the path dropped the probe, which is why the scanner reports open|filtered. A closed port on a live host always answers with RST, so 'closed' was never available here." },
  { ch: 3, type: "study", q: "You scan a host behind a firewall and every probed port reports filtered. What have you actually established?", opts: ["That the host runs no services on those ports", "That the scan ran too fast for the host to keep up with", "That the host is not on the network at all", "That a filtering device is dropping your probes, so you have mapped policy rather than services"], answer: 3, exp: "A dropped probe is information about the router, not the host: it tells you a rule exists in the path. The filtered state says nothing about whether a listener is bound — that is exactly the uncertainty the arithmetic of filtered scans is built on." },
  { ch: 3, type: "study", q: "Why does the Week 3 deck recommend a TUN interface over a TAP interface for most tunnelling work?", opts: ["TUN carries packets at Layer 3, which is enough for almost every protocol, while TAP puts you in the remote broadcast domain and burns bandwidth on traffic you did not ask for", "TUN carries more protocol detail than TAP, so fewer things break", "TUN authenticates the tunnel while TAP does not", "TAP cannot carry IP traffic at all"], answer: 0, exp: "Almost all protocols already run on top of IP, so a Layer 3 TUN interface covers nearly everything. A TAP behaves like plugging into a remote switch: you receive ARP requests and other broadcast chatter you did not want — useful only when you genuinely need Layer 2." },
  { ch: 3, type: "study", q: "You need a service that sits behind a jump host to appear on your own laptop's loopback interface. Which forward do you use?", opts: ["A reverse forward, mapping a remote port back to your local service", "A local forward, mapping a local port through the SSH server to the remote service", "A web proxy, because it caches responses locally", "A TAP interface, because it bridges your loopback to the remote LAN"], answer: 1, exp: "ssh -L 33306:mysql-server:3306 dev@web-server opens a listening socket on your side of the tunnel, and the permitted hop does the dialling. A reverse forward (-R) exposes a service of yours on the remote machine, which is the opposite direction." },
  { ch: 3, type: "math", q: "How many usable host addresses does 10.0.2.0/24 contain, and why is the answer not 256?", opts: ["256, because every address in the prefix can be assigned", "254, because the network address and the broadcast address cannot be assigned to a host", "255, because one address is reserved for the router", "252, because the router and the DHCP server each hold one"], answer: 1, exp: "N_usable = 2^(32−p) − 2 = 2^8 − 2 = 254. The all-zero host part names the network and the all-ones host part is the broadcast address, so neither may be assigned. A router address comes out of the 254; it is not an extra subtraction." },
  { ch: 3, type: "math", q: "A client sends SYN with seq = 4000. The server replies SYN, ACK with seq = 9000. What acknowledgement number does the client's final handshake segment carry?", opts: ["9000", "9001", "4001", "4000"], answer: 1, exp: "The acknowledgement is seq_peer + len(data) + [SYN or FIN present]. The server's SYN consumed one sequence number even though it carried no data, so the client acknowledges 9000 + 0 + 1 = 9001 — the same +1 rule that makes teardown numbers look off by one." },
  { ch: 3, type: "math", q: "You probe 1000 ports on one host with RTT = 10 ms. Using the scan-cost model, roughly how long does each technique take?", opts: ["About 20 s for a connect scan and about 10 s for a SYN scan", "About 10 s for both, because the port count is the same", "About 10 s for a connect scan and about 20 s for a SYN scan", "About 2 s each, because modern scanners pipeline the probes"], answer: 0, exp: "T_connect ≈ n · 2 RTT = 1000 × 2 × 10 ms = 20 s, and T_SYN ≈ n · RTT = 10 s, because a connect scan completes the handshake on every port while a SYN scan sends one segment and abandons the conversation. Both are lower bounds — they ignore retransmission and say nothing about ports that never answer." },
  { ch: 3, type: "math", q: "An ACL contains, in this order: (1) deny printer → finance, (2) permit finance → printer established. A reply from printer to finance on an established connection arrives. What happens?", opts: ["It is denied by rule 1, because deny rules are always evaluated first", "It is denied by the implicit deny at the end of the list", "It is permitted by rule 2, because the reply matches the established-flow rule before rule 1 is reached", "It is permitted, because established traffic bypasses ACLs entirely"], answer: 2, exp: "An ACL is an ordered list where the first match decides, so the list is evaluated in the order written. Rule 1 never matches this packet because the reply is part of an established flow, which is what rule 2 exists to admit. Any packet matching nothing falls through to the implicit deny." },
  { ch: 3, type: "math", q: "Two independent controls each stop an attack with probability 0.8. Under the product model, what is the probability of a breach, and what assumption does it rest on?", opts: ["0.4, because the two failure probabilities add", "0.04, assuming the two controls fail independently", "0.2, because the stronger control dominates the average", "0.64, because each control fails with probability 0.8"], answer: 1, exp: "P(breach) = ∏ p_i = 0.2 × 0.2 = 0.04 when the controls are independent. Written out, the formula exposes its own assumption: controls sharing a credential, a rule set or an unverified identity have P(breach) ≈ p, not p²." },

  /* Ch4 */
  { ch: 4, type: "study", q: "A profile page stores a display name and renders it to every visitor, inserting the value into the HTML without escaping. Which flaw is this, and what is the control that must hold for every render path?", opts: ["CSRF; add an unguessable token to the form", "Stored XSS; validate and sanitise input and encode or escape on output with an anti-XSS library", "Insecure direct object access; implement access controls on the profile record", "Security misconfiguration; configure the server to OWASP and NIST guidance"], answer: 1, exp: "The value is persisted and served to later visitors with no crafted link needed, so it is stored XSS — the more serious form. Input validation reduces what can be stored but does not fix data already stored, which is why output encoding must hold at every render position." },
  { ch: 4, type: "study", q: "An application checks that a user is logged in, then loads the record whose id appears in the URL. Which term of grant = a ∧ z is missing?", opts: ["a, because no session was established", "h, because the response was served from cache", "z, because nothing checks whether this identity may access this object", "Neither — the object identifier is proof enough of entitlement"], answer: 2, exp: "Authentication a was satisfied at login. Authorisation z must be answered per request and per object: treating a user-supplied identifier as entitlement is insecure direct object access, and the same shape as missing function-level access control one level up." },
  { ch: 4, type: "study", q: "A user logged in with a normal account edits one path segment in the URL and reaches the admin console with a 200 response. Which vulnerability is this, and where must the fix live?", opts: ["SQL injection; the fix belongs in the query builder", "Invalidated redirect; the fix belongs in the redirect handler", "Missing function-level access control; the fix belongs in a server-side authorisation check on the function itself", "Broken authentication; the fix belongs in the password policy"], answer: 2, exp: "The application knows who you are but never checks what you may do — a = true with z never evaluated. Hiding the link in the menu is not a control, because removing the link from the request removes the check along with it." },
  { ch: 4, type: "study", q: "A request for another user's invoice returns 200 OK with that user's data. What does the status code alone tell you?", opts: ["The request was rejected but the body was returned anyway", "The response came from cache rather than the database", "The server treated the request as valid and authorised, so no authorisation check stopped it", "Nothing — status codes are unreliable and only the body matters"], answer: 2, exp: "2xx means the request was received, understood and accepted. A 200 in response to a request that should have been refused is the cheapest evidence of missing authorisation, and it needs no access to the server's logs to read." },
  { ch: 4, type: "study", q: "Why does a session cookie make CSRF possible at all?", opts: ["Because JavaScript on any page can read the cookie's value", "Because the browser attaches the cookie automatically to any request for that origin, however that request was triggered", "Because sessions never expire on the server side", "Because cookies are transmitted in clear text over HTTP"], answer: 1, exp: "The browser's habit of attaching the cookie is what the attack abuses; the attacker never needs to read the response or know the token. That is exactly why the CSRF defence — a token that is unguessable and tied to the user — is not the same control as hiding the cookie from script." },
  { ch: 4, type: "study", q: "An application enforces complex passwords and 2FA at login, yet an attacker still reaches another user's data. Which explanation fits the Week 4 material?", opts: ["The password policy was too weak, so the password was guessed", "2FA is not a real defence because attackers can always bypass it", "The session token was stolen after login and replayed, so the second factor was never consulted again", "The application should have used client-side validation in addition to 2FA"], answer: 2, exp: "A second factor protects the login, not a session already issued: once authentication has succeeded, a stolen cookie is replayed as a valid session. Re-authentication for sensitive actions and short session lifetimes are the controls that address the session rather than the login." },
  { ch: 4, type: "study", q: "A WAF blocks your injection attempt while enforcing, and the identical request succeeds once learning mode is enabled. What is the correct conclusion?", opts: ["The application was patched and learning mode temporarily disabled the patch", "The filter is a mitigation layer, not a fix: the vulnerable code is unchanged and the request succeeds whenever the filter is not enforcing", "The filter is ineffective and should be removed", "Learning mode proves the injection is a false positive"], answer: 1, exp: "The only variable between the two runs is the filter's mode, so the filter is the only thing preventing exploitation while the underlying defect is untouched. The deck's own word for WAF protection is 'until' a proper patch is deployed." },
  { ch: 4, type: "study", q: "Which property of a web application most directly explains why an attacker on another continent can reach it without any user action?", opts: ["It is written in HTML, CSS and JavaScript", "It is hosted on a remote server and its interface is HTTP", "It depends on a database, an API and third-party services", "It stores its state in cookies"], answer: 1, exp: "The markable definition names three properties: browser-accessed, remotely hosted and reached over a network, and speaking HTTP. Remote hosting plus an HTTP interface is what makes the application reachable from anywhere — while the layered dependencies widen the blast radius of a single flaw." },
  { ch: 4, type: "math", q: "A search page returns every product in the table when the query contains a quotation mark. Which layer owns this flaw, and why is 'validate the input' an incomplete answer on its own?", opts: ["The web server layer; validation belongs in the server configuration", "The application server layer; validation reduces instances but does not remove the class, because it depends on predicting every dangerous input", "The database layer; the fix is to re-index the products table", "The client layer; the fix is to disable the form's submit button"], answer: 1, exp: "User text assembled into a query can occupy an instruction position, so the flaw belongs to the application server. Validation with an expected format and length is necessary but depends on prediction; keeping the query's structure fixed and binding data into it removes the class, and least-privilege credentials bound what a successful injection reaches." },
  { ch: 4, type: "math", q: "Two users see the same personalised page after a cache warm-up. Which notation describes the fault and which control belongs to it?", opts: ["grant = a ∧ z failed, because the user was not authenticated", "session : token ↦ (identity, permissions) failed, because the token was forged", "t_avg = h·t_hit + (1 − h)·t_miss describes the win, but the response was not keyed on identity and authorisation state, so it was served to the wrong user", "M = learn describes the fault, because the filter only logged the request"], answer: 2, exp: "The cache arithmetic explains why caching survives review — at h = 0.9 roughly 6–12 ms against 50–100 ms uncached. The security condition is the part that gets skipped: a stored response is only safe if it was keyed on the identity and authorisation state entitled to see it, never on the URL alone." },

  /* Ch5 */
  { ch: 5, type: "study", q: "A scanner reports 'possible SQL injection' on a search parameter because the response contained a database error string. What is the most accurate description of that output?", opts: ["A confirmed vulnerability with a known impact", "A candidate finding that still needs validation, ownership and remediation tracking", "A misconfiguration of the web server's error handler", "A false positive that can be closed without further work"], answer: 1, exp: "Automated discovery produces candidates, not verdicts: the indicator is a response difference rather than a proof. Validate, own and track are the deck's own caveat about scanner output, which is why the first action on the ticket is manual reproduction rather than a patch." },
  { ch: 5, type: "study", q: "A team owns the source repository and a CI pipeline but has no running production instance to scan. Which class of scanner can still be used, and what does it cost them?", opts: ["White box scanning, at the cost of the external attacker's perspective", "Black box scanning, at the cost of source code access", "Grey box scanning, because it needs neither source nor a running target", "None — without a running instance no scanner class applies"], answer: 0, exp: "White box scanning examines source code, configuration files and internal messages, so it runs in development and CI. Its characteristic weakness is exactly the missing external perspective — plus complexity and false positives from misreading code." },
  { ch: 5, type: "study", q: "A scanner sends one request per parameter and keeps a benign baseline of each. Which property of good probe design does this describe?", opts: ["Randomising the order of tests to avoid caching effects", "Isolating one variable per request and comparing against a stored baseline", "Maximising requests per second so the scan finishes sooner", "Sending every payload in a single request to reduce noise"], answer: 1, exp: "Changing a single slot means any change in the response stays attributable, and the baseline — the same request with a benign value, stored before any test is sent — is the only thing that makes a diff meaningful. Volume without attribution produces noise, not findings." },
  { ch: 5, type: "study", q: "A scanner configured without a session cookie reports almost nothing on an application whose interesting features are all behind a login. What is the correct reading of that report?", opts: ["The authenticated area of the application is secure", "The scan is dominated by false negatives, because the scanner never reached the protected functionality", "The scanner is misconfigured at the network layer and cannot reach the host", "The findings are all false positives and should be dismissed"], answer: 1, exp: "Without a valid authentication cookie every protected request answers with a redirect to the login page, so coverage of the authenticated part is near zero and the absence of findings says nothing about it. Retrieve the cookie from your own lab session; note it expires and re-authenticate when redirects spike." },
  { ch: 5, type: "study", q: "Why does the tutorial insist on manually confirming an important finding from a ZAP report before demonstrating it?", opts: ["Because automated scanners are not permitted in the unit's labs", "Because a matched risk indicator must be reproduced to show the flaw is real and to identify its cause", "Because scanner reports do not include enough formatting detail", "Because ZAP only reports misconfigurations, not injections"], answer: 1, exp: "The analyse stage of a scanner matches signatures and cannot reason about business logic, so it produces both false positives and false negatives. Reproducing the finding and naming the missing control is what turns an alert into a remediable finding." },
  { ch: 5, type: "study", q: "A report lists the same reflected-input finding against six parameters of one page, and the reflection is HTML-encoded in every case. What is the correct triage outcome?", opts: ["Six confirmed vulnerabilities, because the input is reflected each time", "Dismiss the alerts as false positives, recording the encoding evidence once and noting the duplicate pattern", "Leave all six open until the next scan", "Escalate all six as critical, because reflection always precedes script execution"], answer: 1, exp: "A pattern matched text that is already encoded downstream is a classic false-positive source, and one root cause repeated across parameters is duplicate reporting. Record the encoding evidence once, dismiss the duplicates, and feed the pattern back into tuning the payload set." },
  { ch: 5, type: "study", q: "A team fixes a cross-site scripting flaw by encoding output on the affected page. What does the lifecycle require next?", opts: ["Close the finding, because the control that addresses XSS has been applied", "Retest the finding and run regression tests on the modified components before closing it", "Re-scan the whole application and ignore the changed pages, since the scanner covers them", "Reopen the finding at the next quarterly review"], answer: 1, exp: "The verify stage is what proves the fix worked and did not break anything: retest the finding, then regression test the modified parts of the application. A finding without a verification step and an owner is documentation rather than a control." },
  { ch: 5, type: "math", q: "A scan reports 40 alerts. Manual triage confirms 24 of them and finds 6 further flaws the scan missed. What are the precision and recall?", opts: ["Precision 0.60, recall 0.80", "Precision 0.60, recall 0.60", "Precision 0.80, recall 0.60", "Precision 0.40, recall 0.82"], answer: 0, exp: "TP = 24 and FP = 16, so precision = TP/(TP + FP) = 24/40 = 0.60. Ground truth is TP + FN = 24 + 6 = 30, so recall = TP/(TP + FN) = 24/30 = 0.80. Two alerts in five are wasted analyst time and one real flaw in five was never surfaced." },
  { ch: 5, type: "math", q: "A payload set detects a flaw in one parameter with per-probe probability p = 0.04 and the probes are independent. Roughly how many probes are needed for a 90% chance of detection, and what does halving p cost?", opts: ["About 25 probes; halving p needs about 50", "About 57 probes; halving p needs about 115, so improving the payload set is worth as much as doubling the request count", "About 90 probes; halving p needs about 180", "About 10 probes; halving p needs about 20"], answer: 1, exp: "P(detected) = 1 − (1 − p)^n, so 0.96^n ≤ 0.10 gives n ≈ 56.4, rounded to 57. With p = 0.02 the same target needs n ≈ 114.5, so both n and p matter — and neither can rescue a slot the crawler never discovered." },
  { ch: 5, type: "math", q: "One scan of the lab application discovered D = 400 endpoints, probed P = 260, and produced 30 alerts: 18 true positives and 12 false positives, with 4 further flaws found by manual review. Which statement is defensible?", opts: ["The scan tested two thirds of the surface, so the application is probably clean", "The alert queue is healthy, because only a third of the alerts were wasted effort", "Coverage is 0.65, precision 0.60, recall about 0.82, and triage costs 30 × 15 = 450 analyst-minutes — useful but incomplete and noisy, with the authenticated area as a known blind spot", "The scan is invalid because its precision is below 0.9"], answer: 2, exp: "C = 260/400 = 0.65, Pr = 18/30 = 0.60, Re = 18/22 ≈ 0.818 and F1 ≈ 0.69. The missing third of the surface is the authenticated area, which is exactly where manual review found the extra flaws — so the scan is useful, incomplete and noisy, and the coverage figure belongs next to the result." },

  /* Ch6 */
  { ch: 6, type: "study", q: "A file on a lab host shows -rwsr-xr-x 1 root root. What does the s actually change?", opts: ["It lets every user write to the file as well as execute it", "It makes the program run with the privileges of the file's owner, which here is root", "It marks the file as a script rather than a compiled binary", "It requires the root password to be supplied before the program starts"], answer: 1, exp: "The s in the owner's execute slot is the setuid bit: the process acquires the file owner's effective identity at exec time, and here the owner is root. No password is involved, and the group and other triads (r-x) still deny write access." },
  { ch: 6, type: "study", q: "You have a shell as www-data on a lab host. Why does a root-owned setuid binary in /tmp change your situation so dramatically?", opts: ["Because it lets you read files in /tmp that are otherwise hidden", "Because executing it runs the process with root's effective identity instead of www-data's", "Because the SUID bit requires the root password to be supplied at run time", "Because /tmp is world-writable and therefore trusted by the kernel"], answer: 1, exp: "By the setuid equation euid = owner(f) = 0, so everything the binary starts runs as root — and since it runs an interpreter the attacker can write to, that writable path becomes a root shell. /tmp being writable is what makes the file reachable, not what confers the privilege." },
  { ch: 6, type: "study", q: "A nightly root cron job executes /opt/backup/run.sh, and the directory /opt/backup is writable by www-data. What is the escalation?", opts: ["A compromised www-data shell can change what executes as root, and the change repeats on every run", "The www-data account can read the backup contents", "Cron refuses to run because the directory ownership is inconsistent", "Nothing, because cron only executes files owned by root"], answer: 0, exp: "Write access to the directory is enough to replace the file, and the schedule supplies the privilege — no exploit required. Because the task repeats, the access repeats too, which is what makes cron worse than a one-off escalation. Root-owned scripts in root-owned directories (0700) with no writable ancestors are the control." },
  { ch: 6, type: "study", q: "A colleague proposes the sudoers entry deploy ALL=(ALL) /usr/bin/apt-get so the deployment account can install packages. What is the correct assessment?", opts: ["It is correctly scoped, because only apt-get can be run", "It is over-granted: package handling can execute maintainer scripts as root, so the grant is effectively arbitrary root code execution", "It grants nothing, because sudo still requires the account's password", "It should be replaced by a setuid wrapper around apt-get"], answer: 1, exp: "A delegated command is only as narrow as the command's own capabilities. The lecture's own example scopes the grant to /usr/bin/apt-get update; granting all of apt-get lets a crafted package run maintainer scripts as root. Narrow to the smallest sufficient command, delegate to a group, apply with visudo and log the result." },
  { ch: 6, type: "study", q: "A colleague says 'we changed the SSH port from 22 to 2222, so the SSH server is hardened now.' What is the correct assessment?", opts: ["Correct — the server is hardened because automated scanners only look at port 22", "Correct, and it also upgrades the cipher suite by moving off the default port", "Only partly — moving the port reduces automated scanning, but root login, empty passwords, password-only authentication, weak protocols and idle timeouts are all still open", "Incorrect — changing the port makes the configuration invalid"], answer: 2, exp: "Hardening is subtractive work and the port change removes exactly one thing: the default target of automated scanning. Restrict root login, set PermitEmptyPasswords no, use key-based or two-factor authentication, disable SSHv1 and weak ciphers, and set ClientAliveInterval with ClientAliveCountMax." },
  { ch: 6, type: "study", q: "Which statement about setuid shell scripts is correct?", opts: ["Setuid works on scripts exactly as it does on binaries", "Most kernels ignore the SUID flag on #! scripts, because honouring it would hand every user a scriptable root shell", "Scripts cannot be given the SUID bit at all, so the question does not arise", "Setuid on a script only takes effect when the script is executable by others"], answer: 1, exp: "A script interpreter is a general-purpose program, so honouring SUID on a script would give anyone a trivially scriptable root shell — which is why the tutorial's helper has to be a compiled binary that then invokes an interpreter the attacker can write to." },
  { ch: 6, type: "study", q: "Why is a kernel privilege-escalation bug treated differently from a setuid or sudoers mistake?", opts: ["Because it can only be triggered by an administrator", "Because it is present on a perfectly configured host running an unpatched kernel, needs only local access, and grants root directly", "Because it always requires a remote network position", "Because it is detected automatically by the package manager"], answer: 1, exp: "A misconfiguration is something a careful administrator can avoid; a kernel defect is not. It is a defect rather than a setting, so the only real controls are patching the kernel, monitoring for new CVEs, and limiting who can obtain a local shell in the first place — the shape of CVE-2016-0728 in the keyring facility." },
  { ch: 6, type: "math", q: "A binary is reported as mode 4755. Which description is correct?", opts: ["Setgid is set; owner has rwx, group and others have r-x", "Setuid is set; owner has rwx, group and others have r-x", "The sticky bit is set, so only the owner may delete the file", "Setuid and setgid are both set; owner has rwx, others have r-x"], answer: 1, exp: "The special digit is a sum: 4 setuid, 2 setgid, 1 sticky. So 4755 means setuid with triads 7-5-5 — rwsr-xr-x. A 6 in that position would indicate setuid plus setgid, and setgid alone would be 2755." },
  { ch: 6, type: "math", q: "A file shows -rwSr--r--. What does the capital S mean, and how should it be reported?", opts: ["Setuid is set and active, so the file runs as root whenever it is executed", "Setuid is set but the owner has no execute bit, so the flag is inert — report it as a latent finding one character away from being dangerous", "The file is sticky, so only the owner may delete it", "The mode is invalid and the kernel ignores the whole permission string"], answer: 1, exp: "Lowercase s means setuid plus execute; uppercase S means setuid without execute, so the flag currently has no effect. Decoded: special digit 4, owner triad 6 (rw-), group and other 4, giving 4644. The same rule applies to t versus T for the sticky bit." },
  { ch: 6, type: "math", q: "You audit a host and find /usr/local/bin/backup-helper is mode 4755 owned by root, /etc/cron.d/cleanup runs a script in a www-data-writable directory as root, sudoers grants %support ALL=(ALL) /usr/bin/less, and the kernel is three minor versions behind. Which ranking by how directly each reaches root is correct?", opts: ["Kernel first, then sudoers, then the SUID binary, then cron", "The root-owned setuid binary and the writable root cron script each give an immediate identity change; the sudo delegation gives one only if the permitted command can escape; the stale kernel gives one only where a working local exploit exists", "The stale kernel is the least direct because kernel bugs need remote access", "All four are equally direct, because each ends in a root shell"], answer: 1, exp: "Rank by directness of the identity change: SUID (euid = owner(f) = 0) and a writable root cron script change identity with no exploit at all, a sudo delegation depends on what the permitted command can do — a pager that can open a shell is a root shell with extra steps — and a stale kernel needs a known working local exploit, though its impact is the highest." },

  /* Ch7 */
  { ch: 7, type: "study", q: "Two apps are installed on the same Android device. What does the sandbox guarantee about them by default?", opts: ["Neither can read the other's private files, and they cannot talk to each other except through declared mechanisms such as intents or content providers", "They share one sandbox so their combined permissions can be audited together", "A malicious app cannot cause harm, because the sandbox blocks malicious behaviour", "They can read each other's data as long as neither declares a dangerous permission"], answer: 0, exp: "The sandbox is a user-based protection model in Linux: one app, one UID, one data directory, one process and one ART instance. It bounds reach, not behaviour — a malicious app holding legitimately granted permissions is inside the rules rather than outside them." },
  { ch: 7, type: "study", q: "An app declares only android.permission.INTERNET. What can it do?", opts: ["Read the user's contacts, because it can upload them over the network", "Open network connections, and nothing beyond what its manifest declares and the platform grants", "It must prompt the user at runtime before it can use the network at all", "Reach any hardware on the device, because INTERNET is a kernel-level permission"], answer: 1, exp: "cap(A) = M_A ∩ G_A: declaration alone grants nothing, and a grant that was declared but denied contributes nothing. INTERNET is a normal, install-time permission, so no runtime dialog is involved — and it does not confer contact access, which would need its own declaration and grant." },
  { ch: 7, type: "study", q: "An app declares an exported broadcast receiver that is not protected by a permission. What is the security consequence?", opts: ["Any other app on the device can send it a broadcast and reach whatever logic the receiver runs", "Nothing, because the sandbox prevents apps from communicating with one another", "The receiver is safe as long as it is exported rather than unexported", "The receiver is safe because broadcasts are always delivered only to the sending app"], answer: 0, exp: "accept(A → c) = exp(c) ∧ (guard(c) = ⊥ ∨ guard(c) ∈ cap(A)), so an exported component with no guard accepts every app on the device. Exported with a guard is a contract; exported without one is a public API nobody designed." },
  { ch: 7, type: "study", q: "You must analyse the exact bytes running on a specific test device. Which acquisition route fits, and what does it require?", opts: ["Download from an alternative app store, because those allow direct APK downloads", "Download from Google with a Play CLI client, because vendor signing guarantees fidelity", "Copy it from the ADB shell; ADB lives in the Android SDK platform-tools and the device must have developer mode and USB debugging enabled", "Ask the developer for the source code, since only source proves what runs"], answer: 2, exp: "Pulling the installed package off the device gives the highest fidelity: the bytes analysed are the bytes installed on that device. Alternative stores are the lowest-trust route — the deck warns of malware and hijacked apps — because a mirror's copy may already be repackaged." },
  { ch: 7, type: "study", q: "A colleague argues that adding ProGuard obfuscation makes an app safe from repackaging. What is the correct correction?", opts: ["ProGuard encrypts the DEX, so no disassembler can read the bytecode at all", "ProGuard is unavailable to most developers, so the argument is moot in practice", "Obfuscation raises the cost of understanding the code but does not stop repackaging — the package can still be rebuilt and signed with a different key", "ProGuard prevents re-signing because it stores the original certificate inside the APK"], answer: 2, exp: "ProGuard renames classes, methods and fields and strips unused code, and DexGuard and DashO add encryption — but the lecture is explicit that this is a cost trade-off, not a wall. It makes reading expensive; the signature check, not obfuscation, is what makes substitution visible." },
  { ch: 7, type: "study", q: "What made Janus (2017) significant?", opts: ["A crafted MMS could trigger code execution during media parsing", "A flaw in a pre-installed remote support tool let an attacker control the device remotely", "APK/DEX bytes could be added to a package without changing its signature, so an app could be updated without the developer's knowledge", "It removed the per-app UID, so all apps shared one sandbox"], answer: 2, exp: "Janus exploited entry-wise verification: the scheme constrained each entry and left the surrounding archive unconstrained, so content could be appended. Verify(σ, H(entries)) = ⊤ does not imply the artefact equals the signed artefact — verify the whole artefact, not the parts you enumerated." },
  { ch: 7, type: "study", q: "Which statement correctly separates jailbreaking iOS from rooting Android?", opts: ["Jailbreaking removes iOS's signature check so unsigned apps can run, with no change to the OS; rooting Android obtains superuser access and can go as far as replacing the OS with a custom ROM", "Both are needed only to install apps from outside the official store", "Jailbreaking rewrites the iOS kernel, while rooting only installs extra apps", "They are identical in mechanism and differ only in the platform's name for the same privilege"], answer: 0, exp: "Apple signs every App Store app and iOS verifies those signatures, so jailbreaking defeats code-signing enforcement; the deck is explicit that the OS itself is unchanged. Rooting defeats the privilege model, and because Android already allows sideloading, its distinctive consequence is superuser access — enough to replace the OS entirely." },
  { ch: 7, type: "math", q: "A package declares no dangerous permissions but exports a receiver with no permission guard that writes caller-supplied values into its own database. Which conclusion is best supported?", opts: ["There is no finding, because the app declares no dangerous permissions and therefore cannot reach sensitive data", "The app is malware, because exported receivers always indicate malicious intent", "A real finding: an exported, unguarded receiver is reachable by any app, and it lets a caller write into this app's private storage without holding any permission", "The finding is that the manifest is invalid, because exported components require a permission"], answer: 2, exp: "Reach plus consequence is the finding: exp(c) is true and guard(c) = ⊥, so accept(A → c) holds for any app, and the receiver's code path converts that reach into a write inside the sandbox. The control that removes it is marking the receiver unexported or giving it a signature-level guard." },
  { ch: 7, type: "math", q: "An APK passes signature verification. What has been established?", opts: ["The app is safe to install, because a valid signature means the code was reviewed", "That the artefact matches what was signed by the holder of the signing key — nothing about what the code does, and nothing about integrity if the scheme only checks entries", "That the code has been obfuscated, which is why the signature is required", "That every component in the manifest is unexported, since exported components cannot be signed"], answer: 1, exp: "σ = Sign_Kpriv(H(content)) and verification accepts iff the digest matches under the certificate's public key. It detects a change in the hashed content and identifies the packager; it says nothing about behaviour, and an entry-wise scheme can be appended to — which was Janus." },
  { ch: 7, type: "math", q: "An app declares READ_CONTACTS and CAMERA, and the user grants only CAMERA at the runtime prompt. What is cap(A) with respect to these two?", opts: ["The app can use both, because both were declared in the manifest", "The app can use neither, because a denial invalidates the whole permission set", "The app can use the camera; contact access is not in its capability set because a declaration alone grants nothing", "The app can use contacts but not the camera, because denial applies to the newest permission"], answer: 2, exp: "cap(A) = M_A ∩ G_A, so a declared-but-denied permission contributes nothing and a runtime denial is a real reduction in reach. Equally, a permission that is granted but unnecessary is pure attack surface, because the intersection is only as small as the grant you agreed to." },

];
